function calculateHandlingFee(itemCount, isFragile) {
  if (itemCount <= 0) {
    throw new Error('itemCount must be positive');
  }
  if (isFragile && itemCount > BULK_THRESHOLD) {
    return FRAGILE_BULK_FEE;
  }
  return itemCount > BULK_THRESHOLD ? BULK_FEE : SMALL_FEE;
}

